    coverImage: 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=inferior%20vena%20cava%20filter%20IVCF%20implantation%20deep%20vein%20thrombosis%20prevention&image_size=landscape_16_9'
